    @EventHandler( payloadType=UpdateContractEvent.class )
    public void handle( UpdateContractEvent event) {
    	LOGGER.info("handling UpdateContractEvent - " + event );
    	
	    Contract entity = new Contract();
            entity.setContractId( event.getContractId() );
            entity.setTitle( event.getTitle() );
            entity.setEffectiveDate( event.getEffectiveDate() );
            entity.setExpiryDate( event.getExpiryDate() );
            entity.setRepositoryUrl( event.getRepositoryUrl() );
            entity.setThirdParty( event.getThirdParty() );
            entity.setObligations( event.getObligations() );
            entity.setDataProcessingActivities( event.getDataProcessingActivities() );
            entity.setMatter( event.getMatter() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindContract( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllContract( entity );        
    }
    
